                }
                break;

        case FR_TYPE_INT8:
        case FR_TYPE_INT16:
        case FR_TYPE_INT32:
        case FR_TYPE_INT64:
                /*
                 *      fr_strtoll checks for overflows and calls
                 *      fr_strerror_printf to set an error.
                 */
                if (fr_strtoll(&sinteger, &p, in) < 0) return -1;
                if (*p != '\0') {
                        fr_strerror_printf("Invalid integer value \"%s\"", in);

                        return -1;
                }
                break;

        default:
                fr_assert_fail(NULL);
                return -1;
        }

